   109	    pub fn set_epoch(&mut self, generation: u64, scale_bucket: u32) {
   110	        if self.generation == generation && self.scale_bucket == scale_bucket { return; }
   111	        self.clear();
   112	        self.generation = generation;
   113	        self.scale_bucket = scale_bucket;
   114	        self.clock_epoch = 0;
   115	        self.clock = 0;
   116	    }
