   118	    pub fn stats(&self) -> CacheStats {
   119	        CacheStats { entry_count: self.count, accounted_bytes: self.accounted_bytes(), byte_cap: self.byte_cap,
   120	            generation: self.generation, scale_bucket: self.scale_bucket }
   121	    }
