   123	    fn valid_tile(tile: &Tile) -> bool {
   124	        tile.width() > 0 && tile.height() > 0 && tile.width() <= vexel_raster::MAX_AXIS &&
   125	            tile.height() <= vexel_raster::MAX_AXIS && tile.width().checked_mul(tile.height())
   126	                .and_then(|pixels| usize::try_from(pixels).ok()?.checked_mul(4)) == Some(tile.byte_count())
   127	    }
   128	
   129	    fn accounted_bytes(&self) -> usize { self.metadata_bytes + self.tile_bytes }
   130	    fn find(&self, key: u64) -> Option<usize> { self.slots.iter().position(|entry| entry.as_ref().is_some_and(|e| e.key == key)) }
   131	
   132	    fn lru_slot(&self) -> Option<usize> {
   133	        self.slots.iter().enumerate().filter_map(|(i, e)| e.as_ref().map(|v| (i, v)))
   134	            .min_by_key(|(_, e)| (e.used_epoch, e.used_tick)).map(|(i, _)| i)
   135	    }
   136	
   137	    fn remove(&mut self, index: usize) {
   138	        if let Some(entry) = self.slots[index].take() {
   139	            self.tile_bytes -= entry.tile.byte_count();
   140	            self.count -= 1;
   141	        }
   142	    }
   143	
   144	    fn clear(&mut self) {
   145	        for slot in &mut self.slots { *slot = None; }
   146	        self.count = 0;
   147	        self.tile_bytes = 0;
   148	    }
   149	
   150	    fn next_tick(&mut self) -> u64 {
   151	        if self.clock == u64::MAX { self.clock = 0; self.clock_epoch = self.clock_epoch.wrapping_add(1); }
   152	        self.clock += 1;
   153	        self.clock
   154	    }
